DELETE FROM Language_en_US WHERE Tag='TXT_KEY_CWC_GUIDE_CAPANOCIRCUIT' OR Tag GLOB 'TXT_KEY_CWC_GUIDE_CAPANOCIRCUIT_*';
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_CAPANOCIRCUIT_CIV_HEADING_1','Playstyle and victory plan');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_CAPANOCIRCUIT_CIV_TEXT_1','The Capano Circuit[NEWLINE]Patient combat projects and terrain-trained veterans[NEWLINE]Domination or Science/Culture from successful development[NEWLINE][NEWLINE]Use strong terrain and support to survive repeated attacks on a worthy target, then convert a genuine four-Beta finish into a SEND. Your economy also needs developed Boulder Sectors; combat rewards are conditional.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_CAPANOCIRCUIT_CIV_HEADING_2','Opening priorities');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_CAPANOCIRCUIT_CIV_TEXT_2','Scout Hills and Mountain-adjacent land for legal, nonadjacent Boulder Sectors. Protect Route Setters and build a normal mixed army rather than sacrificing early units in an attempt to manufacture a SEND.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_CAPANOCIRCUIT_CIV_HEADING_3','Develop the engine');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_CAPANOCIRCUIT_CIV_TEXT_3','Choose a durable Project that the same attacker can safely revisit. Maintain ranged support, healing and an escape route while building Beta. A weaker initial target or a different target will not deliver the intended qualifying finish.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_CAPANOCIRCUIT_CIV_HEADING_4','Convert the advantage');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_CAPANOCIRCUIT_CIV_TEXT_4','Preserve successful climbers and their permanent techniques. Combine upgraded Sectors and training with carefully chosen assaults; a defended city can be a valuable Project only if the attacker survives long enough to finish it.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_CAPANOCIRCUIT_CIV_HEADING_5','Strengths');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_CAPANOCIRCUIT_CIV_TEXT_5','- Qualifying SENDs connect combat success to healing, experience and economic rewards.[NEWLINE]- Permanent techniques make surviving specialists increasingly useful.[NEWLINE]- Boulder Sectors add an independent development and training plan.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_CAPANOCIRCUIT_CIV_HEADING_6','Weaknesses and costs');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_CAPANOCIRCUIT_CIV_TEXT_6','- Four-Beta rewards require repeated survival and an initially worthy target.[NEWLINE]- Changing the target abandons the existing Project.[NEWLINE]- Terrain requirements constrain Sector placement and training access.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_CAPANOCIRCUIT_CIV_HEADING_7','How to play against this civilization');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_CAPANOCIRCUIT_CIV_TEXT_7','- Rotate or withdraw a marked defender rather than allowing the same safe attack repeatedly.[NEWLINE]- Focus the Project attacker before it can heal through a finish.[NEWLINE]- Use fast decisive attacks to deny the patient combat sequence.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_CAPANOCIRCUIT_CIV_HEADING_8','Common mistakes');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_CAPANOCIRCUIT_CIV_TEXT_8','- Farming weak targets and expecting a qualifying SEND.[NEWLINE]- Changing targets just before the fourth-Beta finish.[NEWLINE]- Trading away a developed climber for a city that ordinary support could secure.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_CAPANOCIRCUIT_CIV_HEADING_9','Matchup examples - conditional analysis');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_CAPANOCIRCUIT_CIV_TEXT_9','Named custom-civilization matchups are conditional mechanical analysis, not tested win rates. All custom civs are human-only and multiplayer is unsupported; these comparisons are for theorycraft or explicitly configured scenarios, not ordinary random AI opponents. General counterplay applies to normal single-player games.[NEWLINE][NEWLINE]FAVOURABLE OPPORTUNITIES[NEWLINE][NEWLINE]Indigo Champion: Strong developed partners can be valuable qualifying Projects if Capano can survive the exchanges; isolate them rather than fighting Red''s entire support team.[NEWLINE][NEWLINE]The Last City: A durable city can offer a worthy Project, but this is a conditional siege opportunity rather than permission to attack unsupported.[NEWLINE][NEWLINE]THREATS TO RESPECT[NEWLINE][NEWLINE]Beyond the Sky: Mobile units can leave the Project attacker''s reach and exploit a slow, wounded climber.[NEWLINE][NEWLINE]The Urgal: A concentrated attack window can eliminate Project units before their long sequence pays off.');
