INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_CAPANOCIRCUIT_STRATEGY','Use strong terrain and support to survive repeated attacks on a worthy target, then convert a genuine four-Beta finish into a SEND. Your economy also needs developed Boulder Sectors; combat rewards are conditional.[NEWLINE][NEWLINE]Scout Hills and Mountain-adjacent land for legal, nonadjacent Boulder Sectors. Protect Route Setters and build a normal mixed army rather than sacrificing early units in an attempt to manufacture a SEND.[NEWLINE][NEWLINE]Choose a durable Project that the same attacker can safely revisit. Maintain ranged support, healing and an escape route while building Beta. A weaker initial target or a different target will not deliver the intended qualifying finish.[NEWLINE][NEWLINE]Preserve successful climbers and their permanent techniques. Combine upgraded Sectors and training with carefully chosen assaults; a defended city can be a valuable Project only if the attacker survives long enough to finish it.');
