INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_CAPANOCIRCUIT_LEADER_HEADING_2','Priorities and decisions');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_CAPANOCIRCUIT_LEADER_TEXT_2','Scout Hills and Mountain-adjacent land for legal, nonadjacent Boulder Sectors. Protect Route Setters and build a normal mixed army rather than sacrificing early units in an attempt to manufacture a SEND.[NEWLINE][NEWLINE]Choose a durable Project that the same attacker can safely revisit. Maintain ranged support, healing and an escape route while building Beta. A weaker initial target or a different target will not deliver the intended qualifying finish.[NEWLINE][NEWLINE]Preserve successful climbers and their permanent techniques. Combine upgraded Sectors and training with carefully chosen assaults; a defended city can be a valuable Project only if the attacker survives long enough to finish it.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_CAPANOCIRCUIT_LEADER_HEADING_3','Matchup examples - conditional analysis');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_CAPANOCIRCUIT_LEADER_TEXT_3','Named custom-civilization matchups are conditional mechanical analysis, not tested win rates. All custom civs are human-only and multiplayer is unsupported; these comparisons are for theorycraft or explicitly configured scenarios, not ordinary random AI opponents. General counterplay applies to normal single-player games.[NEWLINE][NEWLINE]FAVOURABLE OPPORTUNITIES[NEWLINE][NEWLINE]Indigo Champion: Strong developed partners can be valuable qualifying Projects if Capano can survive the exchanges; isolate them rather than fighting Red''s entire support team.[NEWLINE][NEWLINE]The Last City: A durable city can offer a worthy Project, but this is a conditional siege opportunity rather than permission to attack unsupported.[NEWLINE][NEWLINE]THREATS TO RESPECT[NEWLINE][NEWLINE]Beyond the Sky: Mobile units can leave the Project attacker''s reach and exploit a slow, wounded climber.[NEWLINE][NEWLINE]The Urgal: A concentrated attack window can eliminate Project units before their long sequence pays off.');
